  'animals.learn.title': 'Responsible care guide',
  'animals.learn.lead': 'The basics every animal needs. Read it calmly: at the end there is a short test, and passing it gives you the certificate you need to adopt on Yavaya.',
  'animals.learn.have_certificate': 'You have held your responsible care certificate since {date}.',
  'animals.guide.water_food.title': 'Water and food',
  'animals.guide.water_food.text': 'Clean water all day, in a bowl in the shade that cannot tip over. Food suited to its species, size and age, at regular times. Never give it chocolate, grapes or raisins, onion, garlic, cooked bones or very salty food: they can make it seriously ill or kill it.',
  'animals.guide.shelter.title': 'Roof and shade',
  'animals.guide.shelter.text': 'A dry, clean place protected from sun, rain and wind, where it can rest in peace. A yard without shade, or a dog out in the rain, is not a home. Cats and small dogs live best inside the house.',
  'animals.guide.chains.title': 'No chains',
  'animals.guide.chains.text': 'An animal tied or chained all day suffers: its neck gets hurt, it becomes anxious and turns aggressive out of fear. It needs to move, play and be with its family. If it must be contained, use a fenced yard or walks on a lead, never a permanent chain.',
  'animals.guide.vet.title': 'Vet and vaccines',
  'animals.guide.vet.text': 'Take it to the vet when you adopt it and at least once a year. The rabies vaccine is mandatory and also protects your family. Deworm it inside and out (fleas and ticks) as often as the vet tells you.',
  'animals.guide.sterilise.title': 'Sterilise',
  'animals.guide.sterilise.text': 'Sterilising prevents litters nobody can care for that end up on the street, prevents serious diseases and reduces fights and escapes. It is the most effective way to have fewer abandoned animals. It does not change the animal’s affection or make it "less".',
  'animals.guide.training.title': 'Teaching with respect',
  'animals.guide.training.text': 'Never hit or shout at it. Animals learn when you reward what they do well, with patience, consistency and many repetitions. Physical punishment only teaches fear, and a frightened animal can bite.',
  'animals.guide.heat.title': 'Heat and signs of illness',
  'animals.guide.heat.text': 'In the heat, heavy panting, a lot of drool, weakness or vomiting can be heatstroke: move it to the shade, give it cool water and find a vet. Never leave it inside a closed vehicle. Loss of appetite, bloody diarrhoea or listlessness for more than a day are also reasons to see a vet.',
  'animals.guide.responsibility.title': 'It is for its whole life',
  'animals.guide.responsibility.text': 'A dog or a cat lives 10 to 18 years. Adopting is a commitment for its whole life, also when it grows old or falls ill. If one day you can no longer care for it, return it to whoever gave it to you for adoption or find it a responsible home. Never abandon it: abandoning it is condemning it.',
  'animals.quiz.title': 'Responsible care test',
  'animals.quiz.lead': 'Ten questions about the guide. With {pass} correct answers out of {total} you receive your certificate. You can try as many times as you need.',
  'animals.quiz.submit': 'See my result',
  'animals.quiz.retry': 'Try again',
  'animals.quiz.score': '{score} out of {total} correct.',
  'animals.quiz.passed': 'You passed! You now have your responsible care certificate and can apply to adopt.',
  'animals.quiz.failed': 'Nearly there: you need {pass}. Read the explanations, go over the guide and try again.',
  'animals.quiz.continue': 'Continue with my application',
  'animals.quiz.correct_is': 'Correct answer: {answer}',
  'animals.quiz.sign_in': 'Sign in to take the test and get your certificate.',
  'animals.quiz.1.q': 'When does a dog or a cat need water?',
  'animals.quiz.1.a': 'Only when it is hot',
  'animals.quiz.1.b': 'Always: clean water all day, in the shade',
  'animals.quiz.1.c': 'Once a day, with its food',
  'animals.quiz.1.why': 'Without water an animal dehydrates within hours, especially in the heat of our region.',
  'animals.quiz.2.q': 'Is it all right to keep a dog chained all day?',
  'animals.quiz.2.a': 'Yes, if it has food and water',
  'animals.quiz.2.b': 'No: it causes suffering and injuries and makes it aggressive',
  'animals.quiz.2.c': 'Yes, but only at night',
  'animals.quiz.2.why': 'A permanent chain is one of the most common forms of cruelty. A fenced yard and walks on a lead are the alternative.',
  'animals.quiz.3.q': 'What is sterilising for?',
  'animals.quiz.3.a': 'It prevents unwanted litters that end up on the street, and prevents disease',
  'animals.quiz.3.b': 'It is only cosmetic',
  'animals.quiz.3.c': 'It takes away its affection for its family',
  'animals.quiz.3.why': 'Every unplanned litter means animals someone will have to rescue. Sterilising is the most effective way to reduce abandonment.',
  'animals.quiz.4.q': 'What about the rabies vaccine?',
  'animals.quiz.4.a': 'It is not needed if the animal never leaves the house',
  'animals.quiz.4.b': 'It is given once in a lifetime',
  'animals.quiz.4.c': 'It is mandatory and repeated when the vet says so',
  'animals.quiz.4.why': 'Rabies is fatal and passes to people. The vaccine protects the animal and your family.',
  'animals.quiz.5.q': 'What is the best way to teach a dog?',
  'animals.quiz.5.a': 'Hit it when it misbehaves',
  'animals.quiz.5.b': 'Reward what it does well, with patience and consistency',
  'animals.quiz.5.c': 'Shout so it understands',
  'animals.quiz.5.why': 'Physical punishment teaches fear, not obedience. A frightened animal can bite.',
  'animals.quiz.6.q': 'What can be a sign of heatstroke?',
  'animals.quiz.6.a': 'Heavy panting, a lot of drool and weakness',
  'animals.quiz.6.b': 'Wagging its tail when it sees you',
  'animals.quiz.6.c': 'Sleeping at night',
  'animals.quiz.6.why': 'Heatstroke can kill within minutes: shade, cool water and a vet straight away.',
  'animals.quiz.7.q': 'If one day you can no longer care for your animal, what do you do?',
  'animals.quiz.7.a': 'I leave it on the street or in the countryside',
  'animals.quiz.7.b': 'I return it to whoever gave it to me for adoption, or find it a responsible home',
  'animals.quiz.7.c': 'I leave it tied up at home',
  'animals.quiz.7.why': 'An abandoned animal almost never survives. Whoever gave it to you for adoption would rather have it back.',
  'animals.quiz.8.q': 'Which food is safe for a dog?',
  'animals.quiz.8.a': 'Leftovers with cooked bones and a little chocolate',
  'animals.quiz.8.b': 'Food suited to its species and age, without chocolate, grapes, onion or cooked bones',
  'animals.quiz.8.c': 'Only tortilla',
  'animals.quiz.8.why': 'Chocolate, grapes and onion are toxic, and cooked bones splinter and pierce the gut.',
  'animals.quiz.9.q': 'Does a cat need a vet?',
  'animals.quiz.9.a': 'No, cats look after themselves',
  'animals.quiz.9.b': 'Yes: it also needs vaccines, deworming and sterilisation',
  'animals.quiz.9.c': 'Only if it gets into fights',
  'animals.quiz.9.why': 'Cats hide pain; without check-ups, their illnesses are found late.',
  'animals.quiz.10.q': 'If you see someone abusing an animal, what do you do?',
  'animals.quiz.10.a': 'Nothing, it is none of my business',
  'animals.quiz.10.b': 'I document it if it is safe and report it to the authorities or a rescue organisation',
  'animals.quiz.10.c': 'I confront them violently',
  'animals.quiz.10.why': 'Reporting it protects the animal without putting you in danger. Cruelty can be reported.',
