  'violeta.nav.guardian': 'Reports',
  'violeta.door.eyebrow': 'For women only',
  'violeta.door.title': 'Espacio Violeta',
  'violeta.door.lead': 'A protected place for women going through something hard: a partner who cheated or left, a pregnancy you face alone, abuse, anxiety, sadness. Nobody here knows who you are, and psychologists and psychiatrists with verified licences are here to listen.',
  'violeta.door.left': 'You left Espacio Violeta and we erased everything you wrote. You can come back whenever you want.',
  'violeta.door.danger': 'If you are in danger right now, get somewhere safe and call your country emergency number. This space can listen, but it cannot send help.',
  'violeta.door.promises_title': 'How we protect you',
  'violeta.door.limits_title': 'What you should know',
  'violeta.door.sign_in': 'Sign in with my account',
  'violeta.door.register': 'Create an account',
  'violeta.promise.name.title': 'A name only for here.',
  'violeta.promise.name.text': 'You get a name that is easy to remember, like «Luna 27». Your Yavaya name and YAY ID are never shown, so you can recognise other women without anyone knowing who anyone is.',
  'violeta.promise.sealed.title': 'Encrypted messages.',
  'violeta.promise.sealed.text': 'Everything you write is stored encrypted. Nobody on the Yavaya team has a screen to read it.',
  'violeta.promise.private.title': 'Private means two.',
  'violeta.promise.private.text': 'A private conversation is read only by the two people in it. The one exception is a message that one of you chooses to report.',
  'violeta.promise.silent.title': 'No alerts that give you away.',
  'violeta.promise.silent.text': 'Nothing from this space reaches your notifications or your email. You only see what is new from inside.',
  'violeta.promise.erase.title': 'It erases itself.',
  'violeta.promise.erase.text': 'Room messages are deleted after {days} days and private ones after {private_days}. You can delete yours at any time, or leave and erase everything.',
  'violeta.promise.exit.title': 'Quick exit.',
  'violeta.promise.exit.text': 'The button at the top takes you to another page at once. Esc twice does the same.',
  'violeta.limit.account': 'You need a Yavaya account to enter. Yavaya keeps the link between your account and your name here only so it can remove someone who abuses the space; nobody inside can see it.',
  'violeta.limit.encryption': 'Messages are encrypted on our servers, but not end to end: Yavaya holds the key and uses it only to show you your conversations.',
  'violeta.limit.women': 'We cannot check that every person is a woman: each one promises it on entering, and anyone who lies is removed when someone reports her. Professional licences are verified.',
  'violeta.limit.not_emergency': 'Professionals listen and advise, but they are not an emergency service. What you decide to do afterwards is always your decision.',
  'violeta.limit.device': 'If someone checks your phone, they can see that you use Yavaya. Use private browsing if you can, and clear your history when you finish.',
  'violeta.pledge.woman': 'I am a woman.',
  'violeta.pledge.confidential': 'What I read here stays here: I do not repeat it, copy it or take screenshots.',
  'violeta.pledge.respect': 'I treat everyone with respect, without judging.',
  'violeta.pledge.not_emergency': 'I understand this space is not an emergency service.',
  'violeta.pledge.professional': 'I respect professional confidentiality and the ethics of my profession, and I do not ask for personal details that are not needed.',
  'violeta.join.title': 'Enter Espacio Violeta',
  'violeta.join.submit': 'Enter',
